// src/components/forms/TrackSubmissionPanel.jsx
import React, { useMemo, useState } from 'react';
import DataGrid from '../DataGrid';
import { showToast } from '../../utils/toast';
import {
  applySheetMapping,
  buildColumnConfig,
  buildFieldLabelMap,
  getExcludedGridColumns,
  getFieldName,
  isConversationField,
  isFieldEditableByUser,
  parseConversation,
} from '../../utils/submissionFields';

const APPS_SCRIPT_URL = import.meta.env.VITE_APPS_SCRIPT_URL;

// The tracking id is generated by the Apps Script, so it is not part of `fields`. It is always
// offered as the primary search field.
const SYSTEM_SEARCH_FIELD = {
  'Field Name': 'id',
  Label: 'Tracking ID',
  'Field Type': 'text',
};
const SYSTEM_SEARCH_KEY = 'id';

// Columns the sheet generates (or that identify the record) and that a submitter never needs to
// read back in the result grid.
const SYSTEM_RESULT_COLUMNS = [
  'uuid',
  'id',
  'email',
  'e-mail',
  'email id',
  'email_id',
  'mail',
  'created',
  'created_at',
  'createdat',
  'created at',
  'updated',
  'updated_at',
  'updatedat',
  'updated at',
  'timestamp',
  'time-stamp',
];

// The same columns stay hidden in the record detail: showing the stored email would let anyone who
// opens a search result read the address and replay it in the verification box.
const SYSTEM_RESULT_COLUMN_SET = new Set(
  SYSTEM_RESULT_COLUMNS.map((column) => column.toLowerCase())
);
const isSystemRecordColumn = (key) => SYSTEM_RESULT_COLUMN_SET.has(String(key).toLowerCase().trim());

const isSystemSearchField = (name) => String(name).trim().toLowerCase() === SYSTEM_SEARCH_KEY;

const normalizeType = (field) => String(field?.['Field Type'] || 'text').toLowerCase().trim();

const getListOptions = (field, type) => {
  if (!['select', 'dropdown', 'radio', 'multi-checkbox'].includes(type)) return [];
  return String(field?.List || '')
    .split(',')
    .map((option) => option.trim())
    .filter(Boolean);
};

const isRequiredValue = (value) => {
  if (typeof value === 'boolean') return value;
  const normalized = String(value ?? '').toLowerCase().trim();
  return normalized === 'true' || normalized === 'yes' || normalized === '1';
};

/** First key of the record that looks like an email column. */
const findEmailColumn = (record) =>
  Object.keys(record || {}).find((key) => /e-?mail/i.test(key)) || null;

const INPUT_CLASS =
  'w-full px-4 py-2.5 border border-gray-200 rounded-xl text-base sm:text-sm text-gray-800 bg-white outline-none transition-all focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100 disabled:bg-gray-100 disabled:text-gray-500';

const Control = ({ field, value, onChange, placeholder }) => {
  const type = normalizeType(field);
  const options = getListOptions(field, type);

  if (options.length > 0) {
    return (
      <select className={INPUT_CLASS} value={value ?? ''} onChange={(e) => onChange(e.target.value)}>
        <option value="">Select…</option>
        {options.map((option) => (
          <option key={option} value={option}>
            {option}
          </option>
        ))}
      </select>
    );
  }

  if (type === 'textarea' || type === 'description') {
    return (
      <textarea
        rows={3}
        placeholder={placeholder}
        className={`${INPUT_CLASS} resize-none`}
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value)}
      />
    );
  }

  if (type === 'checkbox') {
    return (
      <label className="inline-flex items-center gap-2 text-sm font-semibold text-gray-700">
        <input
          type="checkbox"
          checked={value === true || String(value).toLowerCase() === 'true'}
          onChange={(e) => onChange(e.target.checked)}
          className="h-4 w-4 rounded accent-indigo-600"
        />
        Yes
      </label>
    );
  }

  const inputType =
    type === 'date'
      ? 'date'
      : type === 'number'
        ? 'number'
        : type === 'email'
          ? 'email'
          : type === 'phone'
            ? 'tel'
            : 'text';

  return (
    <input
      type={inputType}
      placeholder={placeholder}
      className={INPUT_CLASS}
      value={value ?? ''}
      onChange={(e) => onChange(e.target.value)}
    />
  );
};

/**
 * Shows the existing thread and appends a message to it. The stored value stays the JSON array
 * the rest of the app (detail modal, review screen) already understands.
 */
const ConversationEditor = ({ field, value, onChange, author, readOnly = false }) => {
  const [draft, setDraft] = useState('');
  const messages = parseConversation(value);

  const addMessage = () => {
    if (!draft.trim()) return;
    const next = [
      ...messages,
      {
        sender: author || 'Reporter',
        'time-stamp': new Date().toLocaleString(),
        message: draft.trim(),
      },
    ];
    onChange(JSON.stringify(next));
    setDraft('');
  };

  return (
    <div className="sm:col-span-2 space-y-2">
      <div className="border border-gray-200 bg-gray-50/60 rounded-2xl p-3 max-h-56 overflow-y-auto space-y-2">
        {messages.length === 0 ? (
          <p className="text-center py-4 text-xs italic text-gray-400">
            No messages in this thread yet.
          </p>
        ) : (
          messages.map((msg, index) => (
            <div key={index} className="rounded-xl bg-white border border-gray-200 px-3 py-2">
              <div className="text-[9px] font-extrabold uppercase tracking-wide text-indigo-700">
                {msg.sender || 'Reporter'}
                <span className="ml-1.5 font-semibold normal-case tracking-normal text-gray-400">
                  {msg['time-stamp'] || msg.timestamp || ''}
                </span>
              </div>
              <p className="text-[11px] font-semibold text-gray-700 whitespace-pre-line break-words mt-0.5">
                {msg.message || ''}
              </p>
            </div>
          ))
        )}
      </div>
      {!readOnly && (
        <div className="flex flex-col sm:flex-row gap-2">
          <textarea
            rows={2}
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder={`Add a comment to ${field.Label || getFieldName(field)}…`}
            className={`${INPUT_CLASS} resize-none flex-1`}
          />
          <button
            type="button"
            onClick={addMessage}
            disabled={!draft.trim()}
            className="self-end px-4 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white text-xs font-bold transition-all disabled:opacity-50"
          >
            <i className="fas fa-plus mr-1.5" />
            Add Comment
          </button>
        </div>
      )}
    </div>
  );
};

/**
 * "Track Submission" panel for a dynamic form.
 * The tracking ID is the primary search key; when it is left blank the configured fields are used
 * together (AND). Matching records are listed, and the submitter can update the fields their role
 * allows after proving the email they submitted with.
 */
const TrackSubmissionPanel = ({
  uuid,
  fields = [],
  sheetMapping = null,
  searchFields = [],
  idPattern = '',
  userRoles = [],
  user = null,
  fullName = '',
}) => {
  const [searchValues, setSearchValues] = useState({});
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [selected, setSelected] = useState(null);
  const [editValues, setEditValues] = useState({});
  const [verifyEmail, setVerifyEmail] = useState('');
  // Set once the submitter proves the email on the record; it becomes their identity so that
  // `Update Allowed: Reporter` fields unlock even though nobody is signed in.
  const [verifiedEmail, setVerifiedEmail] = useState('');
  const [saving, setSaving] = useState(false);

  // ID is always offered, ahead of every configured field.
  const secondarySearchDefs = useMemo(() => {
    const names = Array.isArray(searchFields) ? searchFields : [];
    return names
      .filter((name) => !isSystemSearchField(name))
      .map((name) =>
        fields.find(
          (field) => getFieldName(field).toLowerCase() === String(name).toLowerCase()
        )
      )
      .filter(Boolean);
  }, [fields, searchFields]);

  const source = useMemo(
    () => ({
      googleSheetId: sheetMapping?.google_sheet_id || null,
      dataSheetName: sheetMapping?.data_sheet_name || null,
    }),
    [sheetMapping]
  );

  const idValue = String(searchValues[SYSTEM_SEARCH_KEY] ?? '').trim();

  const runSearch = async () => {
    // An ID on its own is a complete search: it is never ANDed with the other fields.
    let criteria = {};
    if (idValue) {
      criteria = { id: idValue };
    } else {
      const provided = secondarySearchDefs
        .map((field) => ({
          key: getFieldName(field),
          value: String(searchValues[getFieldName(field)] ?? '').trim(),
        }))
        .filter((entry) => entry.value !== '');

      if (provided.length === 0) {
        showToast(
          secondarySearchDefs.length > 0
            ? 'Enter the tracking ID or fill in the other search fields.'
            : 'Enter your tracking ID to search.',
          'error'
        );
        return;
      }
      criteria = Object.fromEntries(provided.map((entry) => [entry.key, entry.value]));
    }

    setLoading(true);
    setError('');
    setSelected(null);

    try {
      const payload = applySheetMapping({ action: 'search', uuid, criteria }, source);
      const res = await fetch(`${APPS_SCRIPT_URL}?action=search`, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload),
      });
      const result = await res.json();
      if (!result.success) throw new Error(result.error || 'Search failed');
      setResults(Array.isArray(result.data) ? result.data : []);
    } catch (err) {
      setResults([]);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSearchSubmit = (event) => {
    event.preventDefault();
    runSearch();
  };

  const editableFields = useMemo(() => {
    if (!selected) return [];
    const identityUser = verifiedEmail ? { ...(user || {}), email: verifiedEmail } : user;
    const context = {
      userRoles,
      user: identityUser,
      fullName: verifiedEmail || fullName,
      record: selected,
      fields,
    };
    return fields
      .filter((field) => getFieldName(field))
      .filter((field) => isFieldEditableByUser(field, context))
      .filter((field) =>
        Object.keys(selected).some(
          (key) => key.toLowerCase() === getFieldName(field).toLowerCase()
        )
      );
  }, [selected, fields, userRoles, user, fullName, verifiedEmail]);

  const editableKeys = useMemo(
    () => new Set(editableFields.map((field) => getFieldName(field).toLowerCase())),
    [editableFields]
  );

  const recordEmailColumn = selected ? findEmailColumn(selected) : null;
  const needsEmailCheck = Boolean(recordEmailColumn);
  const recordEmailValue = recordEmailColumn
    ? String(selected?.[recordEmailColumn] ?? '').trim()
    : '';
  const isVerified = needsEmailCheck ? Boolean(verifiedEmail) : Boolean(user);

  const openRecord = (record) => {
    const initial = {};
    fields.forEach((field) => {
      const key = getFieldName(field);
      if (!key) return;
      const recordKey = Object.keys(record).find(
        (candidate) => candidate.toLowerCase() === key.toLowerCase()
      );
      initial[key] = recordKey ? (record[recordKey] ?? '') : '';
    });
    setEditValues(initial);
    setSelected(record);

    const emailColumn = findEmailColumn(record);
    const recordEmail = emailColumn ? String(record[emailColumn] ?? '').trim() : '';
    const accountEmail = String(user?.email || '').trim();
    const accountMatches =
      recordEmail && accountEmail && recordEmail.toLowerCase() === accountEmail.toLowerCase();
    setVerifyEmail(accountMatches ? recordEmail : '');
    setVerifiedEmail(accountMatches ? recordEmail : '');
  };

  const handleVerifyEmail = () => {
    const provided = verifyEmail.trim();
    if (!provided) {
      showToast('Enter the email address used in this submission.', 'error');
      return;
    }
    if (provided.toLowerCase() !== recordEmailValue.toLowerCase()) {
      showToast('That email does not match the address on this submission.', 'error');
      return;
    }
    setVerifiedEmail(provided);
    showToast('Email verified. You can now edit the allowed details.', 'success');
  };

  const handleSave = async () => {
    if (!selected) return;
    if (selected.id === undefined || selected.id === null || selected.id === '') {
      showToast("Cannot update this record: it has no 'id' column.", 'error');
      return;
    }

    // Submitters are not signed in, so the verified email is the proof of ownership.
    if (needsEmailCheck) {
      if (!verifiedEmail) {
        showToast('Verify the email used in this submission before saving.', 'error');
        return;
      }
    } else if (!user) {
      showToast('Sign in to update this submission.', 'error');
      return;
    }

    const recordKeyFor = (name) =>
      Object.keys(selected).find((key) => key.toLowerCase() === name.toLowerCase());

    const changes = {};
    for (const field of editableFields) {
      const key = getFieldName(field);
      const recordKey = recordKeyFor(key);
      if (!recordKey) continue;

      const rawValue = editValues[key];
      if (isRequiredValue(field?.['Required']) && String(rawValue ?? '').trim() === '') {
        showToast(`${field.Label || key} is required.`, 'error');
        return;
      }
      if (String(rawValue ?? '') !== String(selected[recordKey] ?? '')) {
        changes[recordKey] = rawValue;
      }
    }

    if (Object.keys(changes).length === 0) {
      showToast('No changes to update.', 'info');
      return;
    }

    setSaving(true);
    try {
      const payload = applySheetMapping(
        {
          action: 'update',
          uuid,
          matchColumn: 'id',
          records: [{ matchValue: selected.id, data: changes }],
        },
        source
      );
      const res = await fetch(APPS_SCRIPT_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload),
      });
      const result = await res.json();
      if (!result.success) throw new Error(result.error || 'Update failed');
      showToast('Your submission was updated.', 'success');
      setSelected(null);
      await runSearch();
    } catch (err) {
      showToast(`Update failed: ${err.message}`, 'error');
    } finally {
      setSaving(false);
    }
  };

  const labelMap = useMemo(() => buildFieldLabelMap(fields), [fields]);
  const excludedColumns = useMemo(
    () => [
      ...new Set([
        ...getExcludedGridColumns(fields, userRoles, ['uuid']),
        ...SYSTEM_RESULT_COLUMNS,
      ]),
    ],
    [fields, userRoles]
  );
  const columnConfig = useMemo(
    () => buildColumnConfig(results || [], labelMap),
    [results, labelMap]
  );

  // Every schema field on the record, editable or not, so the submitter can read the full
  // submission instead of a truncated grid cell. Extra sheet columns are appended read-only, but
  // the system-generated ones (id, email, created, updated, …) are never rendered.
  const recordEntries = useMemo(() => {
    if (!selected) return [];
    const seen = new Set();
    const entries = [];
    fields.forEach((field) => {
      const name = getFieldName(field);
      if (!name || isSystemRecordColumn(name)) return;
      const recordKey = Object.keys(selected).find(
        (candidate) => candidate.toLowerCase() === name.toLowerCase()
      );
      if (!recordKey) return;
      seen.add(recordKey.toLowerCase());
      entries.push({
        field,
        key: name,
        recordKey,
        value: selected[recordKey],
        editable: editableKeys.has(name.toLowerCase()),
      });
    });
    Object.keys(selected).forEach((recordKey) => {
      const lower = recordKey.toLowerCase();
      if (seen.has(lower) || isSystemRecordColumn(recordKey)) return;
      entries.push({
        field: {
          'Field Name': recordKey,
          Label: labelMap[recordKey] || recordKey,
          'Field Type': 'text',
        },
        key: recordKey,
        recordKey,
        value: selected[recordKey],
        editable: false,
      });
    });
    return entries;
  }, [selected, fields, editableKeys, labelMap]);

  const authorName = fullName || user?.email || 'Reporter';

  return (
    <div data-feature="track-submission" className="space-y-6">
      <form
        onSubmit={handleSearchSubmit}
        className="bg-gray-50/70 border border-gray-200 rounded-3xl p-5 sm:p-7 space-y-4"
        data-feature-filter="track-submission"
      >
        <div className="flex items-start gap-3">
          <div className="w-10 h-10 rounded-xl bg-indigo-100 text-indigo-600 flex items-center justify-center shrink-0">
            <i className="fas fa-magnifying-glass" />
          </div>
          <div>
            <h3 className="text-base font-black text-gray-900">Track your submission</h3>
            <p className="text-xs font-semibold text-gray-500 mt-0.5">
              Search by tracking ID, or by the details you submitted, then update the request.
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div className="sm:col-span-2">
            <label className="block text-[11px] font-bold text-gray-600 mb-1.5 uppercase tracking-wide">
              {SYSTEM_SEARCH_FIELD.Label}
            </label>
            <Control
              field={SYSTEM_SEARCH_FIELD}
              value={searchValues[SYSTEM_SEARCH_KEY]}
              onChange={(value) => setSearchValues((prev) => ({ ...prev, id: value }))}
              placeholder={idPattern || 'e.g. ABC-00001'}
            />
            <p className="text-[10px] font-semibold text-gray-500 mt-1">
              {secondarySearchDefs.length > 0
                ? 'The tracking ID alone finds your request. Leave it blank to search with the other fields instead.'
                : 'Enter the tracking ID printed on your submission.'}
            </p>
          </div>

          {secondarySearchDefs.map((field) => {
            const key = getFieldName(field);
            return (
              <div key={key}>
                <label className="block text-[11px] font-bold text-gray-600 mb-1.5 uppercase tracking-wide">
                  {field.Label || key}
                </label>
                <Control
                  field={field}
                  value={searchValues[key]}
                  onChange={(value) => setSearchValues((prev) => ({ ...prev, [key]: value }))}
                />
              </div>
            );
          })}
        </div>

        <div className="flex justify-end">
          <button
            type="submit"
            disabled={loading}
            className="px-5 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-bold transition-all shadow-lg shadow-indigo-100 disabled:opacity-50"
          >
            {loading ? (
              <i className="fas fa-spinner fa-spin mr-2" />
            ) : (
              <i className="fas fa-search mr-2" />
            )}
            Search
          </button>
        </div>
      </form>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 p-4 rounded-2xl text-sm font-medium">
          {error}
        </div>
      )}

      {results !== null && (
        <div data-feature="track-submission-results" className="space-y-4">
          <div className="flex items-center justify-between gap-3">
            <h3 className="text-sm font-black text-gray-800">
              {results.length} matching submission{results.length === 1 ? '' : 's'}
            </h3>
            {results.length > 0 && (
              <p className="text-[11px] font-semibold text-gray-500">
                Select a record to view every field and update the ones you may change.
              </p>
            )}
          </div>

          {results.length === 0 ? (
            <div className="text-center py-10 bg-white border border-dashed border-gray-200 rounded-3xl">
              <i className="fas fa-inbox text-3xl text-gray-300 mb-3 block" />
              <p className="text-sm font-semibold text-gray-600">
                No submissions matched those details.
              </p>
            </div>
          ) : (
            <DataGrid
              data={results}
              loading={loading}
              error=""
              onRowClick={openRecord}
              excludeColumns={excludedColumns}
              columnConfig={columnConfig}
              mobileCardView
            />
          )}
        </div>
      )}

      {selected && (
        <div className="bg-white border border-indigo-100 rounded-3xl p-5 sm:p-7 shadow-sm space-y-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
            <div>
              <h3 className="text-sm font-black text-gray-900">Update submission</h3>
              <p className="text-[11px] font-semibold text-gray-500">
                Tracking ID: {String(selected.id ?? '—')}
              </p>
            </div>
            <button
              type="button"
              onClick={() => setSelected(null)}
              className="text-xs font-bold text-gray-500 hover:text-gray-800 transition-all self-start"
            >
              <i className="fas fa-xmark mr-1" /> Close
            </button>
          </div>

          {needsEmailCheck && !isVerified && (
            <div
              className="rounded-2xl border border-amber-200 bg-amber-50 p-3 sm:p-4 space-y-2"
              data-feature="track-submission-verify"
            >
              <label className="flex items-center gap-1.5 text-[11px] font-extrabold uppercase tracking-wide text-amber-900">
                <i className="fas fa-shield-halved" />
                Verify your email to edit
              </label>
              <div className="flex flex-col sm:flex-row gap-2">
                <input
                  type="email"
                  value={verifyEmail}
                  onChange={(e) => setVerifyEmail(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      handleVerifyEmail();
                    }
                  }}
                  placeholder="Email used in this submission"
                  className={`${INPUT_CLASS} flex-1`}
                />
                <button
                  type="button"
                  onClick={handleVerifyEmail}
                  className="px-4 py-2.5 rounded-xl bg-amber-600 hover:bg-amber-700 text-white text-xs font-bold transition-all shrink-0"
                >
                  <i className="fas fa-unlock mr-1.5" />
                  Verify
                </button>
              </div>
              <p className="text-[10px] font-semibold text-amber-800">
                The details below stay read-only until this matches the email address recorded on
                this submission.
              </p>
            </div>
          )}

          {needsEmailCheck && isVerified && (
            <div
              className="flex flex-wrap items-center justify-between gap-2 rounded-2xl border border-emerald-200 bg-emerald-50 px-3 py-2"
              data-feature="track-submission-verified"
            >
              <p className="text-[11px] font-bold text-emerald-800">
                <i className="fas fa-circle-check mr-1.5" />
                Verified as {verifiedEmail}
              </p>
              <button
                type="button"
                onClick={() => {
                  setVerifiedEmail('');
                  setVerifyEmail('');
                }}
                className="text-[11px] font-bold text-emerald-700 hover:text-emerald-900 underline"
              >
                Use a different email
              </button>
            </div>
          )}

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4" data-feature="track-submission-record">
            {recordEntries.map(({ field, key, value, editable }) => {
              const type = normalizeType(field);
              const raw = value === null || value === undefined ? '' : value;
              const text = typeof raw === 'object' ? JSON.stringify(raw, null, 2) : String(raw);
              const isWide =
                isConversationField(field) ||
                ['textarea', 'description', 'conversation'].includes(type) ||
                text.length > 80 ||
                text.includes('\n');

              if (isConversationField(field)) {
                return (
                  <div key={key} className="sm:col-span-2">
                    <label className="block text-[11px] font-bold text-gray-600 mb-1.5 uppercase tracking-wide">
                      {field.Label || key}
                    </label>
                    <ConversationEditor
                      field={field}
                      value={editValues[key] ?? raw}
                      author={authorName}
                      readOnly={!editable}
                      onChange={(next) => setEditValues((prev) => ({ ...prev, [key]: next }))}
                    />
                  </div>
                );
              }

              return (
                <div key={key} className={isWide ? 'sm:col-span-2' : undefined}>
                  <label className="flex items-center gap-1.5 text-[11px] font-bold text-gray-600 mb-1.5 uppercase tracking-wide">
                    <span>
                      {field.Label || key}
                      {editable && isRequiredValue(field?.['Required']) && (
                        <span className="text-red-500 ml-1">*</span>
                      )}
                    </span>
                    {!editable && (
                      <i className="fas fa-lock text-[9px] text-gray-400" title="Read only" />
                    )}
                  </label>
                  {editable ? (
                    <Control
                      field={field}
                      value={editValues[key]}
                      onChange={(next) => setEditValues((prev) => ({ ...prev, [key]: next }))}
                    />
                  ) : (
                    <div
                      className={`rounded-xl border px-3.5 py-2.5 text-sm font-semibold break-words whitespace-pre-wrap ${
                        text === ''
                          ? 'border-gray-100 bg-gray-50/60 text-gray-400 italic'
                          : 'border-gray-200 bg-gray-50 text-gray-800'
                      }`}
                    >
                      {text === '' ? 'Not provided' : text}
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          {!isVerified ? (
            <p className="text-xs font-semibold text-amber-700 bg-amber-50 border border-amber-200 rounded-xl p-3">
              Verify the email on this submission to unlock the details you are allowed to change.
            </p>
          ) : editableFields.length === 0 ? (
            <p className="text-xs font-semibold text-amber-700 bg-amber-50 border border-amber-200 rounded-xl p-3">
              You can view this submission but your role cannot change any of its details. Contact
              the office if something needs to change.
            </p>
          ) : (
            <div className="flex flex-wrap justify-end gap-2">
              <button
                type="button"
                onClick={() => setSelected(null)}
                className="px-4 py-2.5 rounded-xl border border-gray-200 bg-white text-sm font-bold text-gray-600 hover:bg-gray-50 transition-all"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleSave}
                disabled={saving}
                className="px-5 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-bold transition-all shadow-lg shadow-indigo-100 disabled:opacity-50"
              >
                {saving ? (
                  <i className="fas fa-spinner fa-spin mr-2" />
                ) : (
                  <i className="fas fa-save mr-2" />
                )}
                Save changes
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default TrackSubmissionPanel;
